let state;try{state=JSON.parse(localStorage.getItem('chnowa-v1'))||{}}catch{state={}}let lang=state.lang==='fr'?'fr':'ar',filter='all',savedOnly=false,active=null;state.favs=state.favs||[];state.checks=state.checks||{};state.mode=state.mode||{};const ix=()=>lang==='ar'?0:1;const tr=(a,b)=>lang==='ar'?a:b;
function persist(){try{localStorage.setItem('chnowa-v1',JSON.stringify(state));return true}catch{toast(tr('ما نجّمناش نحفظو في المتصفّح هذا.','Ce navigateur ne permet pas la sauvegarde.'));return false}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function render(){document.documentElement.lang=lang==='ar'?'ar-TN':'fr';document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-t]').forEach(el=>el.innerHTML=ui[lang][el.dataset.t]);$('#language').innerHTML=lang==='ar'?'FR <span>↗</span>':'العربية <span>↗</span>';$('#search').placeholder=tr('شنوّة تحب تعمل؟','Quelle démarche recherchez-vous ?');$('#saved').textContent=savedOnly?tr('كل الأدلة','Tous les guides'):ui[lang].saved;const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[أإآ]/g,'ا').toLowerCase();const q=normalize($('#search').value.trim());const aliases={cin:'cin',sajalni:'phone',passport:'passport'};const list=guides.filter(g=>(filter==='all'||g.cat===filter)&&(!savedOnly||state.favs.includes(g.id))&&(!q||normalize([...g.title,...g.desc,g.keys,g.id].join(' ')).includes(q)||aliases[q]===g.id));$('#count').textContent=`${list.length} / ${guides.length} `+tr('أدلة','guides');$('#empty').hidden=list.length>0;$('#empty').textContent=savedOnly?tr('ما عندكش أدلة محفوظة توّا. افتح دليل واضغط «احفظ الدليل».','Aucun favori. Ouvrez un guide puis cliquez sur « Enregistrer ».'):ui[lang].empty;$('#cards').innerHTML=list.map(g=>`<button class="card" data-id="${g.id}"><div class="card-top"><span class="icon"><svg viewBox="0 0 24 24" aria-hidden="true">${paths[g.icon]}</svg></span><span class="tag">${ui[lang][g.cat]}</span></div><h3>${g.title[ix()]}</h3><p>${g.desc[ix()]}</p><div class="card-bottom"><span>${state.favs.includes(g.id)?'★ ':''}${g.steps.length} ${tr('خطوات أساسية','étapes essentielles')}</span><b>${tr('نشوف الدليل ←','Voir le guide →')}</b></div></button>`).join('');}
function stepsFor(g){const steps=g.steps.map((s,i)=>({key:'base'+i,text:s[ix()]}));if(g.extra){const mode=state.mode[g.id]||'first';const extra=g.extra[mode]||[];extra.forEach((s,i)=>steps.splice(steps.length-1,0,{key:mode+i,text:s[ix()]}))}return steps}
function detail(){const g=guides.find(g=>g.id===active);if(!g)return;const steps=stepsFor(g),checks=state.checks[g.id]||{};const done=steps.filter(s=>checks[s.key]).length;$('#dialog-tag').textContent=ui[lang][g.cat]+' / '+tr('دليل عملي','GUIDE PRATIQUE');$('#detail').innerHTML=`<h2 id="guide-title">${g.title[ix()]}</h2><p>${g.desc[ix()]}</p><div class="detail-actions"><button id="favorite">${state.favs.includes(g.id)?tr('★ محفوظ · إلغاء الحفظ','★ Enregistré · Retirer'):tr('☆ احفظ الدليل','☆ Enregistrer')}</button><button id="print">${tr('اطبع القائمة','Imprimer')}</button><button id="reset">${tr('عاود من الأول','Réinitialiser')}</button></div>${g.extra?`<label for="mode">${tr('شنوّة وضعيتك؟ اختار الحالة الرئيسية.','Votre situation principale :')}</label><select id="mode"><option value="first">${tr('أوّل طلب · بالغ','Première demande · adulte')}</option><option value="renew">${tr('تجديد · بالغ','Renouvellement · adulte')}</option><option value="student">${tr('تلميذ أو طالب · أوّل طلب','Élève ou étudiant · première demande')}</option><option value="minor">${tr('قاصر · أوّل طلب','Mineur · première demande')}</option></select>`:''}<div class="notice">${g.old?tr('المصدر الإداري قديم: هاذي قائمة تحضيرية، موش تأكيد للقواعد الحالية. ثبّت في الوثائق، التعريفة والآجال عند المركز قبل ما تمشي. للمقيمين بالخارج، راجع القنصلية.','La source administrative est ancienne : cette liste aide à préparer, sans confirmer les règles actuelles. Vérifiez pièces, tarifs et délais auprès du poste. À l’étranger, consultez votre consulat.'):tr('هاذي خطوات تحضيرية. المصدر فيه الشروط والتفاصيل الكاملة؛ ثبّت في المعاليم والآجال عند المصلحة المعنية.','Ce guide prépare votre démarche. Consultez la source pour les conditions et la liste complète ; confirmez les frais et délais auprès du service.')} ${g.extra?tr('إذا وضعيتك تجمع أكثر من حالة، راجع الشروط الكل في المصدر.','Si plusieurs situations s’appliquent, consultez toutes les conditions de la source.'):''}</div><h3>${tr('قائمتي','Ma checklist')} <small id="done">${done}/${steps.length}</small></h3><div class="progress"><span style="width:${done/steps.length*100}%"></span></div>${steps.map(s=>`<label class="checkrow"><input type="checkbox" data-key="${s.key}" ${checks[s.key]?'checked':''}><span>${s.text}</span></label>`).join('')}<h3>${tr('لوين نمشي؟','Où faire la démarche ?')}</h3><p>${g.where[ix()]}</p><h3>${tr('المصدر والتفاصيل','Source et détails')}</h3><a class="source" href="${g.source}" target="_blank" rel="noopener">${g.sourceName} ↗</a>${(g.links||[]).map(l=>`<a class="source" href="${l[1]}" target="_blank" rel="noopener">${l[0]} ↗</a>`).join('')}<p>${tr('آخر مراجعة للمصادر: 11 أكتوبر 2026. تقدّمك يتحفظ في المتصفّح هذا برك، من غير وثائق ولا بيانات هوية.','Sources consultées le 11 octobre 2026. Votre progression reste dans ce navigateur ; aucun document ni renseignement d’identité demandé.')}</p>`;if(g.extra)$('#mode').value=state.mode[g.id]||'first';}
$('#cards').addEventListener('click',e=>{const card=e.target.closest('[data-id]');if(!card)return;active=card.dataset.id;detail();$('#guide').showModal()});$('#close').onclick=()=>$('#guide').close();$('#guide').addEventListener('click',e=>{if(e.target===$('#guide')){const r=$('#guide').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#guide').close()}});
$('#detail').addEventListener('click',e=>{if(e.target.id==='favorite'){if(state.favs.includes(active))state.favs=state.favs.filter(id=>id!==active);else state.favs.push(active);persist();detail();render()}if(e.target.id==='print')window.print();if(e.target.id==='reset'){state.checks[active]={};persist();detail()}});
$('#detail').addEventListener('change',e=>{if(e.target.dataset.key){state.checks[active]=state.checks[active]||{};state.checks[active][e.target.dataset.key]=e.target.checked;persist();const g=guides.find(g=>g.id===active),steps=stepsFor(g),done=steps.filter(s=>state.checks[active][s.key]).length;$('#done').textContent=`${done}/${steps.length}`;$('.progress span').style.width=done/steps.length*100+'%'}if(e.target.id==='mode'){state.mode[active]=e.target.value;persist();detail()}});
$('#language').onclick=()=>{lang=lang==='ar'?'fr':'ar';state.lang=lang;persist();render();if($('#guide').open)detail()};$('#search').addEventListener('input',render);$('#searchform').onsubmit=e=>{e.preventDefault();render();$('#guides').scrollIntoView({behavior:'smooth'})};document.querySelectorAll('[data-query]').forEach(b=>b.onclick=()=>{$('#search').value=b.dataset.query;filter='all';savedOnly=false;document.querySelectorAll('[data-filter]').forEach(f=>f.classList.toggle('active',f.dataset.filter==='all'));render();$('#guides').scrollIntoView({behavior:'smooth'})});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(f=>f.classList.toggle('active',f===b));render()});$('#saved').onclick=()=>{savedOnly=!savedOnly;filter='all';$('#search').value='';document.querySelectorAll('[data-filter]').forEach(f=>f.classList.toggle('active',f.dataset.filter==='all'));render();$('#guides').scrollIntoView({behavior:'smooth'})};render();
